const reduced=matchMedia("(prefers-reduced-motion: reduce)").matches;
function progress(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(max>0?scrollY/max*100:0)+'%'}addEventListener('scroll',progress,{passive:true});progress();
const sequence=document.querySelector('.scroll-sequence'),cards=[...document.querySelectorAll('.info-card')];let queued=false;function animateSequence(){queued=false;if(reduced)return;const r=sequence.getBoundingClientRect(),distance=Math.max(1,r.height-innerHeight),p=Math.max(0,Math.min(1,-r.top/distance));cards.forEach((card,i)=>{const t=Math.max(0,Math.min(1,(p-i*.27)/.23));card.style.transform=`translate3d(0,${(1-t)*(innerHeight+50)}px,0)`;card.style.visibility=t>0?'visible':'hidden'})}function requestSequence(){if(!queued){queued=true;requestAnimationFrame(animateSequence)}}addEventListener('scroll',requestSequence,{passive:true});addEventListener('resize',requestSequence);animateSequence();